 static string Payload { get { return Path.Combine(StageRoot,"payload"); } }
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static string Hash(string path) { using(var input=File.OpenRead(path))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant(); }
 static void Require(bool ok,string message) { if(!ok)throw new InvalidOperationException(message); }
 static void NoReparse(string path) {
  for(var cursor=Path.GetFullPath(path);cursor!=null;cursor=Path.GetDirectoryName(cursor))
   Require((File.GetAttributes(cursor)&FileAttributes.ReparsePoint)==0,"Reparse point rejected.");
