 static void ImmutableParents(string path) {
  var trusted=new[]{"S-1-5-18","S-1-5-32-544","S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464"};
  var danger=FileSystemRights.Delete|FileSystemRights.DeleteSubdirectoriesAndFiles|FileSystemRights.ChangePermissions|FileSystemRights.TakeOwnership;
  for(var cursor=Path.GetDirectoryName(Path.GetFullPath(path));cursor!=null;cursor=Path.GetDirectoryName(cursor)) {
