 public static bool SafeEntry(string name,int attributes) {
  if(String.IsNullOrEmpty(name)||name.StartsWith("/")||name.IndexOf('\\')>=0||name.IndexOf(':')>=0||((attributes>>16)&0xf000)==0xa000)return false;
  foreach(var segment in name.TrimEnd('/').Split('/')) {
   if(segment==""||segment=="."||segment==".."||segment.EndsWith(".")||segment.EndsWith(" ")||segment.IndexOfAny(Path.GetInvalidFileNameChars())>=0)return false;
   var stem=segment.Split('.')[0].ToUpperInvariant();
   if(stem=="CON"||stem=="PRN"||stem=="AUX"||stem=="NUL"||stem=="CLOCK$"||(stem.Length==4&&(stem.StartsWith("COM")||stem.StartsWith("LPT"))&&stem[3]>='1'&&stem[3]<='9'))return false;
  }
