 static void VerifyPayload(string archive) {
  Protected(StageRoot);Protected(archive);Require(Hash(archive)==Release.ArchiveSha256,"Embedded archive checksum mismatch.");
  Protected(Payload);
  // Verify against the embedded ZIP entries, not a caller-edited manifest/hash file.
  using(var zip=ZipFile.OpenRead(archive)) {
   Require(zip.Entries.Count>0&&zip.Entries.Count<=4096,"Archive entry limit.");long total=0;
   var expected=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   foreach(var entry in zip.Entries) {
    Require(SafeEntry(entry.FullName,entry.ExternalAttributes),"Unsafe archive entry.");total+=entry.Length;Require(total<=64L*1024*1024,"Archive size limit.");
    var target=Path.GetFullPath(Path.Combine(Payload,entry.FullName.Replace('/',Path.DirectorySeparatorChar)));
    Require(target.StartsWith(Payload+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"Archive traversal.");
    Protected(target);
    if(entry.FullName.EndsWith("/",StringComparison.Ordinal))continue;
    Require(expected.Add(target),"Duplicate archive file.");
    using(var source=entry.Open())using(var sha=SHA256.Create())Require(Hash(target)==BitConverter.ToString(sha.ComputeHash(source)).Replace("-","").ToLowerInvariant(),"Extracted package mismatch.");
   }
   foreach(var file in Directory.GetFiles(Payload,"*",SearchOption.AllDirectories))Require(expected.Contains(file),"Unexpected staged file.");
   foreach(var directory in Directory.GetDirectories(Payload,"*",SearchOption.AllDirectories))Protected(directory);
  }
  var manifest=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Payload,"vm-package-manifest.json")));
  Require((string)manifest["Commit"]==Release.Commit,"Package commit mismatch.");
 }
 static void Extract() {
  Require(Environment.Is64BitProcess&&Environment.OSVersion.Platform==PlatformID.Win32NT,"Windows x64 required.");
  Require(new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator),"Administrator session required.");
  var parent=Path.GetDirectoryName(StageRoot);Require(Directory.Exists(parent),"Existing protected SmartHome ProgramData root required.");
  ImmutableParents(StageRoot);Protected(parent);
  var archive=Path.Combine(StageRoot,"package.zip");
  if(Directory.Exists(StageRoot)) { VerifyPayload(archive);return; }
  Directory.CreateDirectory(StageRoot);ProtectDirectory(StageRoot);Protected(StageRoot);
  using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("SmartHomePayload.zip")) {
   Require(input!=null,"Embedded package missing.");using(var output=new FileStream(archive,FileMode.CreateNew,FileAccess.Write,FileShare.None))input.CopyTo(output);
  }
  ProtectFile(archive);
  Require(Hash(archive)==Release.ArchiveSha256,"Embedded archive checksum mismatch.");
  using(var zip=ZipFile.OpenRead(archive)) {
   long total=0;Require(zip.Entries.Count>0&&zip.Entries.Count<=4096,"Archive entry limit.");
   var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   foreach(var entry in zip.Entries) {total+=entry.Length;Require(SafeEntry(entry.FullName,entry.ExternalAttributes)&&seen.Add(entry.FullName.TrimEnd('/'))&&total<=64L*1024*1024,"Unsafe embedded archive.");}
  }
  ZipFile.ExtractToDirectory(archive,Payload);ProtectExtractedTree();VerifyPayload(archive);
 }
 static string RunInstaller(string mode) {
  Extract();var shell=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),@"System32\WindowsPowerShell\v1.0\powershell.exe");
  var psi=new ProcessStartInfo { FileName=shell,Arguments="-NoProfile -NonInteractive -ExecutionPolicy RemoteSigned -File \""+Path.Combine(Payload,@"scripts\Install-VmManagement.ps1")+"\" -Mode "+mode+" -PackageRoot \""+Payload+"\"",UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true };
  using(var process=Process.Start(psi)) {
   var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();
   // Never force-kill an installer in a transaction. Its own subprocesses are bounded.
   process.WaitForExit();var text=stdout.Result+stderr.Result;
   Require(process.ExitCode==0,"Installer stopped. Preserve staging/backups.\r\n"+text);return text;
  }
 }
 [STAThread] public static int Main(string[] args) {
  if(args.Length>0) {
   // Headless packaging checks only; no caller-selected installer operations or arguments.
   if(args.Length!=1||args[0]!="verify-package")return 2;
   try {
    Require(SafeEntry("scripts/Install-VmManagement.ps1",0)&&!SafeEntry("../escape",0)&&!SafeEntry("C:/escape",0)&&!SafeEntry("x\\escape",0)&&!SafeEntry("server/CON.js",0)&&!SafeEntry("alias. ",0)&&!SafeEntry("link",unchecked((int)0xa0000000)),"Archive path policy failed.");
    Extract();Console.WriteLine("SETUP PACKAGE PASS: "+Release.Commit);return 0;
   }catch(Exception e){Console.Error.WriteLine(e.Message);return 2;}
  }
  Application.EnableVisualStyles();var form=new Form { Text="Smart Home VM Management Setup — "+Release.Commit,Width=1000,Height=700 };
  var log=new TextBox { Multiline=true,ReadOnly=true,WordWrap=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill };
  var controls=new FlowLayoutPanel { Dock=DockStyle.Top,Height=90,AutoSize=true };
  bool installed=File.Exists(Path.Combine(InstalledRoot,"installed.json")),running=false;
  log.Text="Verify this EXE's external release SHA-256 before running.\r\nPinned package: "+Release.Commit+"\r\n"+(installed?"Existing boundary detected: this package does not upgrade or replace its binaries. Verify is available; native boundary upgrades require a separate reviewed procedure.":"Existing healthy SYSTEM MCP task, protected configuration, Node 24 and Windows Firewall are prerequisites. This package does not install a new MCP service or elevate an existing service.")+"\r\nInitial production cutover always requires independent approval in the operator window.\r\n";
  foreach(var mode in new[]{"Preflight","HardenRuntime","Install","Verify","Recover","Uninstall"}) {
   var action=mode;var button=new Button { Text=mode=="Install"?"Install boundary":mode,AutoSize=true,Enabled=!installed||mode=="Verify"||mode=="Recover"||mode=="Uninstall" };
   controls.Controls.Add(button);
   button.Click+=(sender,e)=> {
    if(running)return;
    if(action!="Preflight"&&action!="Verify") {
     var scope=action=="HardenRuntime"?"Tighten approved existing runtime/tunnel permissions with a protected ACL backup; preserve content, credentials and service processes.":action=="Install"?"Provision the separate management boundary. Existing MCP task privileges/configuration are preserved; no production cutover.":action=="Recover"?"Disable management and restore the original MCP configuration/runtime; a service restart may occur.":"Remove only the new management boundary after verified recovery; retain audit/recovery inventory.";
     if(MessageBox.Show(scope+"\r\n\r\nProceed with "+action+"?","Administrator installation action",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;
